    }
    const eventLocations = new Map<number, ConversationLocation>([[
      3,
      { kind: 'step', turn, step },
    ]])

    const turns = deriveTrajectoryLayout({
      nodes,
      eventLocations,
      partial: null,
      runningCalls: [],
      requests: [{
