        status: 'running',
      }],
    })

    expect(turns[0]?.groups[0]?.cells).toMatchObject([
      { kind: 'user', previewMarkdown: 'change direction', sourceSeq: 3 },
      { kind: 'message', requestOnly: true, sourceSeq: 2 },
